// src/layoutEngines.ts
import { fmmmLayout } from "@jbrowse/graph-fmmm-layout";
import { stressLayout } from "@jbrowse/graph-stress-layout";
var LAYOUT_ENGINES = [
  {
    value: "fmmm",
    label: "Bandage (FMMM)",
    description: "Bandage's force-directed layout: OGDF's fast multipole multilevel method, compiled to wasm."
  },
  {
    value: "stress",
    label: "Stress",
    description: "Plain JS: the reference drawn straight and each variant placed against it, an allele as a lens, a repeat loop as a ring, a deletion as an arch; stress by stochastic gradient descent for components with no reference."
  }
];
var LAYOUT_ENGINE_VALUES = LAYOUT_ENGINES.map((e) => e.value);
function isLayoutEngineKind(value) {
  return LAYOUT_ENGINE_VALUES.includes(value);
}
var layoutEngine = async (request) => {
  if (request.options.engine === "stress") {
    const start2 = performance.now();
    const result2 = stressLayout(request);
    return { result: result2, duration: performance.now() - start2 };
  }
  const start = performance.now();
  const result = await fmmmLayout(request);
  return { result, duration: performance.now() - start };
};

export {
  LAYOUT_ENGINES,
  LAYOUT_ENGINE_VALUES,
  isLayoutEngineKind,
  layoutEngine
};
